    sets={'x+abs':np.column_stack([X[:,ix],absx]),
          'x+abs+pairs':np.column_stack([X[:,ix],absx,P]),
          'x+abs+dev':np.column_stack([X[:,ix],absx,np.abs(X[:,ix]-np.median(X[:,ix],1)[:,None])]),
          'full':np.column_stack([X[:,ix],absx,P,np.abs(X[:,ix]-np.median(X[:,ix],1)[:,None]),np.median(X[:,ix],1)])}
    for k,F in sets.items(): print('h%d'%t,k,F.shape[1],np.round(sub('h%d'%t,F),3))
